// Command aligncheck generates and manages struct alignment tests for
// github.com/marshone/aligncheck.
//
// Usage:
//
//	aligncheck gen [-prefix name] [-f] <package-dir>
//	aligncheck test [go test flags] [packages]
//	aligncheck inspect [-arch name] [-v] [packages]
//	aligncheck ls [root]
//	aligncheck clean [-y] [root]
//	aligncheck version
package main

import (
	"errors"
	"flag"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"runtime/debug"
	"sort"
	"strings"
)

// signature marks generated files. It matches the header written by
// gen_alignment_test.sh, so ls and clean also find files made by the script.
const signature = "// Auto Generated by github.com/marshone/aligncheck"

const usageText = `aligncheck - manage struct alignment tests

Usage:
  aligncheck gen [-prefix name] [-f] <package-dir>   generate <prefix>_test.go for a package
  aligncheck test [go test flags] [packages]         run the alignment tests (go test -run TestStructAlignments)
  aligncheck inspect [-arch name] [-v] [packages]    report struct layouts directly, without tests
  aligncheck ls [root]                               list generated alignment tests
  aligncheck clean [-y] [root]                       remove generated alignment tests
  aligncheck version                                 print the version

Flags must come before the directory argument.
`

func main() {
	if len(os.Args) < 2 {
		fmt.Fprint(os.Stderr, usageText)
		os.Exit(2)
	}

	var err error
	switch os.Args[1] {
	case "gen":
		err = runGen(os.Args[2:])
	case "test":
		err = runTest(os.Args[2:])
	case "inspect":
		err = runInspect(os.Args[2:])
	case "ls":
		err = runLs(os.Args[2:])
	case "clean":
		err = runClean(os.Args[2:])
	case "version", "-v", "--version":
		fmt.Println("aligncheck", version())
	case "help", "-h", "--help":
		fmt.Print(usageText)
	default:
		fmt.Fprintf(os.Stderr, "aligncheck: unknown command %q\n\n%s", os.Args[1], usageText)
		os.Exit(2)
	}

	if err != nil {
		fmt.Fprintln(os.Stderr, "aligncheck:", err)
		os.Exit(1)
	}
}

func runGen(args []string) error {
	flags := flag.NewFlagSet("gen", flag.ContinueOnError)
	prefix := flags.String("prefix", "struct_alignment", "output file name prefix (<prefix>_test.go)")
	force := flags.Bool("f", false, "overwrite an existing generated file")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if flags.NArg() != 1 {
		return errors.New("gen: expected exactly one package directory")
	}

	res, err := generate(flags.Arg(0), *prefix, *force)
	if err != nil {
		return err
	}
	for _, name := range res.Skipped {
		fmt.Fprintf(os.Stderr, "skipped generic struct %s: register an instantiation by hand\n", name)
	}
	if res.Path == "" {
		fmt.Printf("no structs found in %s\n", flags.Arg(0))
		return nil
	}
	fmt.Printf("wrote %s (%d structs)\n", res.Path, len(res.Structs))
	return nil
}

// runTest runs the alignment tests through go test, passing every argument
// through, and exits with go test's own exit code.
func runTest(args []string) error {
	goArgs := append([]string{"test", "-run", "^TestStructAlignments$", "-count=1"}, args...)
	cmd := exec.Command("go", goArgs...)
	cmd.Stdin, cmd.Stdout, cmd.Stderr = os.Stdin, os.Stdout, os.Stderr
	err := cmd.Run()
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		os.Exit(exitErr.ExitCode())
	}
	return err
}

func runLs(args []string) error {
	flags := flag.NewFlagSet("ls", flag.ContinueOnError)
	if err := flags.Parse(args); err != nil {
		return err
	}
	files, err := findGenerated(rootArg(flags))
	if err != nil {
		return err
	}
	if len(files) == 0 {
		fmt.Println("no generated alignment tests found")
	}
	for _, f := range files {
		fmt.Println(f)
	}
	return nil
}

func runClean(args []string) error {
	flags := flag.NewFlagSet("clean", flag.ContinueOnError)
	yes := flags.Bool("y", false, "delete without asking (default: dry run)")
	if err := flags.Parse(args); err != nil {
		return err
	}
	files, err := findGenerated(rootArg(flags))
	if err != nil {
		return err
	}
	if len(files) == 0 {
		fmt.Println("no generated alignment tests found")
		return nil
	}
	if !*yes {
		fmt.Println("would delete:")
		for _, f := range files {
			fmt.Println("  " + f)
		}
		fmt.Println("rerun with -y to delete")
		return nil
	}
	for _, f := range files {
		if err := os.Remove(f); err != nil {
			return err
		}
		fmt.Println("deleted", f)
	}
	return nil
}

func rootArg(flags *flag.FlagSet) string {
	if flags.NArg() > 0 {
		return flags.Arg(0)
	}
	return "."
}

// genResult describes what generate wrote. Path is empty when the package
// has no structs to register.
type genResult struct {
	Path    string
	Structs []string
	Skipped []string
}

// generate writes <dir>/<prefix>_test.go registering every top-level struct
// declared in the package's non-test files, including grouped type blocks.
func generate(dir, prefix string, force bool) (genResult, error) {
	var res genResult
	outName := prefix + "_test.go"

	fset := token.NewFileSet()
	pkgs, err := parser.ParseDir(fset, dir, nil, parser.SkipObjectResolution)
	if err != nil {
		return res, fmt.Errorf("parse %s: %w", dir, err)
	}

	pkgNames := map[string]bool{}
	seen := map[string]bool{}
	for _, pkg := range pkgs {
		for path, file := range pkg.Files {
			if strings.HasSuffix(path, "_test.go") {
				// Two TestStructAlignments in one package would not compile.
				if filepath.Base(path) != outName && declaresTest(file) {
					return res, fmt.Errorf("%s already declares TestStructAlignments", path)
				}
				continue
			}
			pkgNames[file.Name.Name] = true
			for _, decl := range file.Decls {
				gen, ok := decl.(*ast.GenDecl)
				if !ok || gen.Tok != token.TYPE {
					continue
				}
				for _, spec := range gen.Specs {
					ts := spec.(*ast.TypeSpec)
					if _, isStruct := ts.Type.(*ast.StructType); !isStruct || seen[ts.Name.Name] {
						continue
					}
					seen[ts.Name.Name] = true
					if ts.TypeParams != nil {
						res.Skipped = append(res.Skipped, ts.Name.Name)
						continue
					}
					res.Structs = append(res.Structs, ts.Name.Name)
				}
			}
		}
	}

	if len(pkgNames) == 0 {
		return res, fmt.Errorf("no Go package found in %s", dir)
	}
	if len(pkgNames) > 1 {
		return res, fmt.Errorf("%s contains more than one package", dir)
	}
	if len(res.Structs) == 0 {
		return res, nil
	}
	sort.Strings(res.Structs)
	sort.Strings(res.Skipped)

	out := filepath.Join(dir, outName)
	if _, err := os.Stat(out); err == nil {
		if !isGenerated(out) {
			return res, fmt.Errorf("%s exists and was not generated by aligncheck; refusing to overwrite", out)
		}
		if !force {
			return res, fmt.Errorf("%s already exists (use -f to overwrite)", out)
		}
	}

	var pkgName string
	for name := range pkgNames {
		pkgName = name
	}

	var b strings.Builder
	fmt.Fprintf(&b, "%s\n// Code generated by aligncheck gen %s; DO NOT EDIT.\n\n", signature, version())
	fmt.Fprintf(&b, "package %s\n\nimport (\n\t\"testing\"\n\n\t\"github.com/marshone/aligncheck\"\n)\n\n", pkgName)
	b.WriteString("func TestStructAlignments(t *testing.T) {\n\tregistry := map[string]any{\n")
	for _, name := range res.Structs {
		fmt.Fprintf(&b, "\t\t%q: %s{},\n", name, name)
	}
	b.WriteString("\t}\n\n\taligncheck.AssertAllInPackageAligned(t, registry)\n}\n")

	src, err := format.Source([]byte(b.String()))
	if err != nil {
		return res, fmt.Errorf("format generated test: %w", err)
	}
	if err := os.WriteFile(out, src, 0o644); err != nil {
		return res, err
	}
	res.Path = out
	return res, nil
}

func declaresTest(file *ast.File) bool {
	for _, decl := range file.Decls {
		if fn, ok := decl.(*ast.FuncDecl); ok && fn.Recv == nil && fn.Name.Name == "TestStructAlignments" {
			return true
		}
	}
	return false
}

// findGenerated returns every *_test.go under root that starts with the
// aligncheck signature. Hidden directories, vendor and testdata are skipped.
func findGenerated(root string) ([]string, error) {
	var found []string
	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			name := d.Name()
			if path != root && (strings.HasPrefix(name, ".") || name == "vendor" || name == "testdata") {
				return filepath.SkipDir
			}
			return nil
		}
		if strings.HasSuffix(path, "_test.go") && isGenerated(path) {
			found = append(found, path)
		}
		return nil
	})
	return found, err
}

func isGenerated(path string) bool {
	data, err := os.ReadFile(path)
	return err == nil && strings.HasPrefix(string(data), signature)
}

// version reports the module version when installed with
// `go install` or `go run ...@version`, and "(devel)" for local builds.
func version() string {
	if info, ok := debug.ReadBuildInfo(); ok && info.Main.Version != "" {
		return info.Main.Version
	}
	return "(devel)"
}
